    private typealias Point = (Int, String, String, String, String)
    private struct BranchSpec {
        let id, title: String
        let anchor: Int
        let condition, explanation, uci: String
    }
    private static func branch(_ id: String, title: String, anchor: Int, condition: String, explanation: String, uci: String) -> BranchSpec {
        BranchSpec(id: id, title: title, anchor: anchor, condition: condition, explanation: explanation, uci: uci)
    }
    /// Non-checkpoint prose is deliberately a factual description, not fabricated
    /// human expertise. Tactical claims live in the individually authored points.
    private static func explainedMoves(fen: String, uci: String, notes: [Int:String] = [:], hints: [Int:String] = [:]) -> [StudyMove] {
        var position = try! Position(fen: fen)
        return uci.split(separator: " ").enumerated().map { index, token in
            let coordinate = String(token), move = Move(uci: coordinate)!
            let name = position.notation(for: move)
            let captured = position[move.to]
            let next = try! position.applying(move: move)
            var fact = "本地引擎参考续着：" + name + "。"
            if let captured { fact += "本步吃到" + captured.symbol + "；应重新评估剩余子力与控制。"}
            if next.legalMoves().isEmpty {
                fact += next.isInCheck(next.sideToMove) ? "末局受将且无合法应招，为将死。" : "末局未受将但无合法着法，为困毙；象棋中同样判负。"
            } else if next.isInCheck(next.sideToMove) { fact += "形成将军，对方下一手必须合法应将。" }
            else { fact += "尚未终局；继续检查对手的将军、吃子与保护变化。" }
            position = next
            return StudyMove(coordinate, notes[index] ?? fact, hint: hints[index] ?? "在当前棋面检查将军、吃子、受攻子和下一步配合；参考续着不保证是唯一选择。")
        }
    }
    private static func line(_ id: String, title: String, intent: String, adaptation: String,
                             fen: String, side: Side = .red, uci: String, points: [Point],
                             branches: [BranchSpec] = []) -> StudyLine {
        let notes = Dictionary(uniqueKeysWithValues: points.map { ($0.0, $0.4) })
        let hints = Dictionary(uniqueKeysWithValues: points.map { ($0.0, $0.3) })
        let moves = explainedMoves(fen: fen, uci: uci, notes: notes, hints: hints)
        var result = StudyLine(id: "school-" + id, title: title,
            intent: "原创教学例。" + intent,
            adaptation: adaptation + " 参考线路由本地引擎生成并经规则逐手核验；学习时允许经评估可行的其他着法，不要求对手配合。",
            startingFEN: fen, studentSide: side, moves: moves,
            checkpoints: points.map { StudyCheckpoint(ply: $0.0, title: $0.1, prompt: $0.2, focus: $0.3, explanation: $0.4) })
        let positions = try! result.positions()
        result.variations = branches.isEmpty ? nil : branches.map {
            StudyVariation(id: $0.id, title: $0.title, anchorPly: $0.anchor,
                condition: $0.condition, explanation: $0.explanation,
                moves: explainedMoves(fen: positions[$0.anchor].fen, uci: $0.uci))
        }
        return result
    }

